llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Zilascorb(2H), a benzylidene-protected ascorbic acid derivative, had an absolute oral bioavailability of 34 ± 13% in patients after 500 mg tablets, directly supporting F ≥ 20% for the ascorbic acid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Mannitol, a small polar sugar alcohol, showed 63% absolute oral bioavailability in healthy men, indicating that small hydrophilic sugar-like molecules can be well absorbed orally; transferability is limited by structural distance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fructose, a monosaccharide, had only 14.5% systemic availability after oral dosing due to first-pass splanchnic extraction; this is structurally distant and mechanistically different from ascorbic acid's active absorption, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most direct evidence is zilascorb(2H), an ascorbic acid derivative, with absolute oral bioavailability of 32-34% in patients, above the 20% threshold. Additional sugar-like molecules are mixed, but the low fructose value is structurally distant and mechanistically different. Overall, the evidence supports high oral bioavailability for the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for L-ascorbic acid itself; the closest analogue is a protected derivative.",
    "Oral bioavailability of ascorbic acid is dose-dependent; the evidence does not cover the full dose range relevant to the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

